#include <stdio.h>
#include <stddef.h>

struct Spread { char first; int number; char last; };
struct Grouped { int number; char first; char last; };

int main(void)
{
    printf("First at zero: %d\n", offsetof(struct Spread, first) == 0);
    printf("No overlap: %d\n", offsetof(struct Spread, last)
           >= offsetof(struct Spread, number) + sizeof(int));
    printf("Enough space: %d\n", sizeof(struct Spread)
           >= offsetof(struct Spread, last) + sizeof(char));
    return 0;
}

#include <stdio.h>

struct Spread { char first; int number; char last; };
struct Grouped { int number; char first; char last; };

int main(void)
{
    struct Spread a = {.first = 'A', .number = 7, .last = 'Z'};
    struct Spread b = {.first = 'A', .number = 7, .last = 'Z'};
    int equal = a.first == b.first && a.number == b.number && a.last == b.last;
    printf("Equal fields: %d\n", equal);
    return 0;
}

#include <stdio.h>

struct Spread { char first; int number; char last; };
struct Grouped { int number; char first; char last; };

int main(void)
{
    struct Spread first = {'A', 12, 'Z'};
    struct Spread second = first;
    second.number = 20;
    printf("%d %d\n", first.number, second.number);
    return 0;
}

